// Writes addon/Werkbank/Data.lua from site/data.js, so the website and the addon use the same recipes.
// addon/build.sh runs it; the generated file is committed, and test/sync/data.test.mjs fails when it is
// out of date. Run: node addon/build-data.mjs
//
// One statement per item and recipe instead of one big table literal: WoW runs Lua 5.1, which limits
// how large a single expression may get.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { CLASSES, RACES, PROFESSIONS } from "../api/armory.mjs";

const here = p => fileURLToPath(new URL(p, import.meta.url));
export const SOURCE = here("../site/data.js");
export const TARGET = here("./Werkbank/Data.lua");

// English profession names by skill line; the German ones, and class and race names, come from
// api/armory.mjs, so the addon names everything like the website. English: site/data.js and English clients.
const PROF_EN = {
  171: "Alchemy", 164: "Blacksmithing", 333: "Enchanting", 202: "Engineering", 165: "Leatherworking", 197: "Tailoring",
  186: "Mining", 182: "Herbalism", 393: "Skinning", 185: "Cooking", 129: "First Aid", 356: "Fishing",
};

export function readData(file = SOURCE) {
  return new Function(readFileSync(file, "utf8") + ";return DATA")();
}

// Lua 5.1 string: the source is UTF-8 text without control characters, so only \ and " need escaping
const str = s => `"${String(s).replace(/[\\"]/g, c => "\\" + c).replace(/\n/g, "\\n")}"`;
const val = v => (typeof v === "string" ? str(v) : Array.isArray(v) ? `{${v.map(val).join(",")}}` : String(v));
// { [1]="…", … } for objects keyed by number
const byId = o => `{${Object.entries(o).map(([k, v]) => `[${k}]=${val(v)}`).join(",")}}`;

export function toLua(D) {
  const unnamed = Object.keys(PROFESSIONS).filter(id => !PROF_EN[id]);
  if (unnamed.length) throw new Error(`no English name for skill line(s): ${unnamed.join(", ")}`);
  const de = Object.fromEntries(Object.entries(PROF_EN).map(([id, en]) => [en, PROFESSIONS[id]]));
  const missing = D.profs.filter(p => !de[p]);
  if (missing.length) throw new Error(`no German name for profession(s): ${missing.join(", ")}`);
  const out = [
    "-- Generated by addon/build-data.mjs from site/data.js. Do not edit; run the generator instead.",
    "-- items[id] = { en, quality, class, sub, slot, reqLevel, gather group, source, source detail, ilvl, de }",
    "-- recipes[n] = { product id, prof, skill, yMin, yMax, { { reagent id, amount } }, recipe item, tool }",
    "-- class, sub, slot and prof are 0-based indexes into the lists below, as in site/data.js.",
    "-- Enchants have no item: their id is the negative spell id.",
    "local _, ns = ...",
    "local D = {}",
    "ns.Data = D",
    `D.profs = ${val(D.profs)}`,
    `D.profsDe = ${val(D.profs.map(p => de[p]))}`,
    `D.classes = ${val(D.classes)}`,
    `D.subs = ${val(D.subs)}`,
    `D.slots = ${val(D.slots)}`,
    "-- names by id, from api/armory.mjs: skill line -> { German, English }, class id, race id",
    `D.profNames = ${byId(Object.fromEntries(Object.entries(PROFESSIONS).map(([id, name]) => [id, [name, PROF_EN[id]]])))}`,
    `D.classNames = ${byId(CLASSES)}`,
    `D.raceNames = ${byId(RACES)}`,
    "local I = {}",
    "D.items = I",
  ];
  const ids = Object.keys(D.items).map(Number).sort((a, b) => a - b);
  for (const id of ids) out.push(`I[${id}] = ${val(D.items[id])}`);
  out.push("local R = {}", "D.recipes = R");
  D.recipes.forEach((r, n) => out.push(`R[${n + 1}] = ${val([...r.slice(0, 7), r[7] || 0])}`));
  out.push(
    "",
    "-- indexes, like site/index.html builds them: recipes by product, recipes by reagent, recipes by profession.",
    "-- D.index(n) also takes recipes the addon reads from the game later (Core.addRecipe).",
    "D.byProduct, D.usedIn, D.byProf = {}, {}, {}",
    "function D.index(n)",
    "  local r = R[n]",
    "  local t = D.byProduct[r[1]] or {}",
    "  t[#t + 1] = n",
    "  D.byProduct[r[1]] = t",
    "  for _, x in ipairs(r[6]) do",
    "    local u = D.usedIn[x[1]] or {}",
    "    u[n] = true",
    "    D.usedIn[x[1]] = u",
    "  end",
    "  local prof = D.profsDe[r[2] + 1]",
    "  local p = D.byProf[prof] or {}",
    "  p[#p + 1] = n",
    "  D.byProf[prof] = p",
    "end",
    "for n in ipairs(R) do D.index(n) end",
    "",
    "return D",
    "",
  );
  return out.join("\n");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const lua = toLua(readData());
  writeFileSync(TARGET, lua);
  console.log(`addon/Werkbank/Data.lua: ${(lua.length / 1024).toFixed(0)} KB`);
}
